+package org.apache.streampipes.rest.security;
+
+import org.apache.streampipes.commons.exceptions.SpRuntimeException;
+
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.URISyntaxException;
+import java.net.UnknownHostException;
+import java.util.Arrays;
+import java.util.List;
+
+public class UrlValidator {
+
+  private static final List<String> ALLOWED_SCHEMES = Arrays.asList("http", "https");
+
+  public static boolean isValidExternalUrl(String urlString) throws SpRuntimeException {
+    try {
+      URI uri = new URI(urlString);
+      
+      // Validate scheme
+      String scheme = uri.getScheme();
+      if (scheme == null || !ALLOWED_SCHEMES.contains(scheme.toLowerCase())) {
+        throw new SpRuntimeException("URL scheme must be http or https");
+      }
+      
+      // Validate host is present
+      String host = uri.getHost();
+      if (host == null || host.isEmpty()) {
+        throw new SpRuntimeException("URL must have a valid host");
+      }
+      
+      // Resolve and validate the host doesn't point to private/internal addresses
+      InetAddress[] addresses = InetAddress.getAllByName(host);
+      for (InetAddress address : addresses) {
+        if (isInternalAddress(address)) {
+          throw new SpRuntimeException("URL host resolves to a private or internal address");
+        }
+      }
+      
+      return true;
+    } catch (URISyntaxException e) {
+      throw new SpRuntimeException("Invalid URL format: " + e.getMessage());
+    } catch (UnknownHostException e) {
+      throw new SpRuntimeException("Unable to resolve host: " + e.getMessage());
+    }
+  }
+
+  private static boolean isInternalAddress(InetAddress address) {
+    return address.isAnyLocalAddress() 
+        || address.isLoopbackAddress()
+        || address.isSiteLocalAddress()
+        || address.isLinkLocalAddress()
+        || isPrivateIpAddress(address.getHostAddress());
+  }
+
+  private static boolean isPrivateIpAddress(String ipAddress) {
+    if (ipAddress == null) {
+      return false;
+    }
+    
+    // Check for IPv4 private ranges
+    if (ipAddress.startsWith("10.")) {
+      return true;
+    }
+    if (ipAddress.startsWith("172.")) {
+      String[] parts = ipAddress.split("\\.");
+      if (parts.length >= 2) {
+        try {
+          int secondOctet = Integer.parseInt(parts[1]);
+          if (secondOctet >= 16 && secondOctet <= 31) {
+            return true;
+          }
+        } catch (NumberFormatException e) {
+          return false;
+        }
+      }
+    }
+    if (ipAddress.startsWith("192.168.")) {
+      return true;
+    }
+    if (ipAddress.startsWith("169.254.")) {
+      return true;
+    }
+    if (ipAddress.equals("0.0.0.0")) {
+      return true;
+    }
+    
+    // Check for IPv6 private/loopback
+    if (ipAddress.equals("::1") || ipAddress.equals("0:0:0:0:0:0:0:1")) {
+      return true;
+    }
+    if (ipAddress.startsWith("fc") || ipAddress.startsWith("fd")) {
+      return true;
+    }
+    
+    return false;
+  }
+}

