+/**
+ * Validates image dimensions to prevent denial of service via excessive memory allocation.
+ * @param {number} width - The width of the image.
+ * @param {number} height - The height of the image.
+ * @returns {boolean} True if dimensions are valid, false otherwise.
+ */
+export function validateImageDimensions(width, height) {
+    const MAX_DIMENSION = 65535; // Maximum supported by jsPDF
+    const MAX_PIXELS = 100000000; // 100 million pixels limit to prevent OOM
+
+    if (width <= 0 || height <= 0) {
+        return false;
+    }
+
+    if (width > MAX_DIMENSION || height > MAX_DIMENSION) {
+        return false;
+    }
+
+    return (width * height) <= MAX_PIXELS;
+}
